namespace CSharpPracticum.Tasks.Level2;
internal interface IDiscountStrategy{decimal Apply(decimal price);} internal class NoDiscount:IDiscountStrategy{public decimal Apply(decimal p)=>p;}internal class VipDiscount:IDiscountStrategy{public decimal Apply(decimal p)=>p*.9m;}internal class PromoDiscount:IDiscountStrategy{public decimal Apply(decimal p)=>p*.8m;}internal class PriceCalculator(IDiscountStrategy strategy){public decimal Calculate(decimal p)=>strategy.Apply(p);}
internal class Task26_Discounts:ITask{public string Title=>"Задание 26: Паттерн Стратегия (скидки)";public string Description=>"Рассчитать цену с взаимозаменяемыми стратегиями скидок.";public string[] Requirements=>new[]{"IDiscountStrategy.Apply(decimal).","NoDiscount, VipDiscount 10%, PromoDiscount 20%.","PriceCalculator принимает стратегию в конструкторе."};public void Run(){foreach(IDiscountStrategy s in new IDiscountStrategy[]{new NoDiscount(),new VipDiscount(),new PromoDiscount()})Console.WriteLine(new PriceCalculator(s).Calculate(100));}}
